--
-- Table structure for table `wp_posts`
--

DROP TABLE IF EXISTS `wp_posts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wp_posts` (
  `ID` bigint unsigned NOT NULL AUTO_INCREMENT,
  `post_author` bigint unsigned NOT NULL DEFAULT '0',
  `post_date` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_date_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content` longtext COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_title` text COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_excerpt` text COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_status` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'publish',
  `comment_status` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'open',
  `ping_status` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'open',
  `post_password` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `post_name` varchar(200) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `to_ping` text COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `pinged` text COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_modified` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_modified_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content_filtered` longtext COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_parent` bigint unsigned NOT NULL DEFAULT '0',
  `guid` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `menu_order` int NOT NULL DEFAULT '0',
  `post_type` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'post',
  `post_mime_type` varchar(100) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `comment_count` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`ID`),
  KEY `post_name` (`post_name`(191)),
  KEY `type_status_date` (`post_type`,`post_status`,`post_date`,`ID`),
  KEY `post_parent` (`post_parent`),
  KEY `post_author` (`post_author`),
  KEY `type_status_author` (`post_type`,`post_status`,`post_author`)
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `wp_posts`
--

LOCK TABLES `wp_posts` WRITE;
/*!40000 ALTER TABLE `wp_posts` DISABLE KEYS */;
INSERT INTO `wp_posts` VALUES (2,1,'2026-09-10 15:11:04','2026-09-10 15:11:04','<!-- wp:paragraph -->\n<p>Đây là trang mẫu. Nó khác với bài viết bởi vì nó thường cố định và hiển thị trong menu của bạn. Nhiều người bắt đầu với trang Giới thiệu nơi bạn chia sẻ thông tin cho những ai ghé thăm. Nó có thể bắt đầu như thế này:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>Chào bạn! Tôi là một người bán hàng, và đây là website của tôi. Tôi sống ở Hà Nội, có một gia đình nhỏ, và tôi thấy cách sử dụng WordPress rất thú vị.</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>... hoặc cái gì đó như thế này:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>Công ty chúng tôi được thành lập năm 2010, và cung cấp dịch vụ chất lượng cho rất nhiều sự kiện tại khắp Việt Nam. Với văn phòng đặt tại Hà Nội, TP. Hồ Chí Minh cùng hơn 40 nhân sự, chúng tôi là nơi nhiều đối tác tin tưởng giao cho tổ chức các sự kiện lớn.</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>Là một người dùng WordPress mới, bạn nên ghé thăm <a href=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-admin/\">bảng điều khiển</a> để xóa trang này và tạo trang mới cho nội dung của chính bạn. Chúc bạn vui vẻ!</p>\n<!-- /wp:paragraph -->','Trang mẫu','','publish','closed','open','','trang-mau','','','2026-09-10 15:11:04','2026-09-10 15:11:04','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/?page_id=2',0,'page','',0),(3,1,'2026-09-10 15:11:04','2026-09-10 15:11:04','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Chúng tôi là ai</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Văn bản được đề xuất: </strong>Địa chỉ website là: http://localhost/BuiNguyenMinhQuan_CMS.git.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Bình luận</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Văn bản được đề xuất: </strong>Khi khách truy cập để lại bình luận trên trang web, chúng tôi thu thập dữ liệu được hiển thị trong biểu mẫu bình luận và cũng là địa chỉ IP của người truy cập và chuỗi user agent của người dùng trình duyệt để giúp phát hiện bình luận rác</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Một chuỗi ẩn danh được tạo từ địa chỉ email của bạn (còn được gọi là hash) có thể được cung cấp cho dịch vụ Gravatar để xem bạn có đang sử dụng nó hay không. Chính sách bảo mật của dịch vụ Gravatar có tại đây: https://automattic.com/privacy/. Sau khi chấp nhận bình luận của bạn, ảnh tiểu sử của bạn được hiển thị công khai trong ngữ cảnh bình luận của bạn.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Thư viện</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Văn bản được đề xuất: </strong>Nếu bạn tải hình ảnh lên trang web, bạn nên tránh tải lên hình ảnh có dữ liệu vị trí được nhúng (EXIF GPS) đi kèm. Khách truy cập vào trang web có thể tải xuống và giải nén bất kỳ dữ liệu vị trí nào từ hình ảnh trên trang web.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Cookies</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Văn bản được đề xuất: </strong>Nếu bạn viết bình luận trong website, bạn có thể cung cấp cần nhập tên, email địa chỉ website trong cookie. Các thông tin này nhằm giúp bạn không cần nhập thông tin nhiều lần khi viết bình luận khác. Cookie này sẽ được lưu giữ trong một năm.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Nếu bạn vào trang đăng nhập, chúng tôi sẽ thiết lập một cookie tạm thời để xác định nếu trình duyệt cho phép sử dụng cookie. Cookie này không bao gồm thông tin cá nhân và sẽ được gỡ bỏ khi bạn đóng trình duyệt.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Khi bạn đăng nhập, chúng tôi sẽ thiết lập một vài cookie để lưu thông tin đăng nhập và lựa chọn hiển thị. Thông tin đăng nhập gần nhất lưu trong hai ngày, và lựa chọn hiển thị gần nhất lưu trong một năm. Nếu bạn chọn &quot;Nhớ tôi&quot;, thông tin đăng nhập sẽ được lưu trong hai tuần. Nếu bạn thoát tài khoản, thông tin cookie đăng nhập sẽ bị xoá.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Nếu bạn sửa hoặc xuất bản bài viết, một bản cookie bổ sung sẽ được lưu trong trình duyệt. Cookie này không chứa thông tin cá nhân và chỉ đơn giản bao gồm ID của bài viết bạn đã sửa. Nó tự động hết hạn sau 1 ngày.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Nội dung nhúng từ website khác</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Văn bản được đề xuất: </strong>Các bài viết trên trang web này có thể bao gồm nội dung được nhúng (ví dụ: video, hình ảnh, bài viết, v.v.). Nội dung được nhúng từ các trang web khác hoạt động theo cùng một cách chính xác như khi khách truy cập đã truy cập trang web khác.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Những website này có thể thu thập dữ liệu về bạn, sử dụng cookie, nhúng các trình theo dõi của bên thứ ba và giám sát tương tác của bạn với nội dung được nhúng đó, bao gồm theo dõi tương tác của bạn với nội dung được nhúng nếu bạn có tài khoản và đã đăng nhập vào trang web đó.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Chúng tôi chia sẻ dữ liệu của bạn với ai</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Văn bản được đề xuất: </strong>Nếu bạn yêu cầu đặt lại mật khẩu, địa chỉ IP của bạn sẽ được bao gồm trong email đặt lại.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Dữ liệu của bạn tồn tại bao lâu</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Văn bản được đề xuất: </strong>Nếu bạn để lại bình luận, bình luận và siêu dữ liệu của nó sẽ được giữ lại vô thời hạn. Điều này là để chúng tôi có thể tự động nhận ra và chấp nhận bất kỳ bình luận nào thay vì giữ chúng trong khu vực đợi kiểm duyệt.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Đối với người dùng đăng ký trên trang web của chúng tôi (nếu có), chúng tôi cũng lưu trữ thông tin cá nhân mà họ cung cấp trong hồ sơ người dùng của họ. Tất cả người dùng có thể xem, chỉnh sửa hoặc xóa thông tin cá nhân của họ bất kỳ lúc nào (ngoại trừ họ không thể thay đổi tên người dùng của họ). Quản trị viên trang web cũng có thể xem và chỉnh sửa thông tin đó.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Các quyền nào của bạn với dữ liệu của mình</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Văn bản được đề xuất: </strong>Nếu bạn có tài khoản trên trang web này hoặc đã để lại nhận xét, bạn có thể yêu cầu nhận tệp xuất dữ liệu cá nhân mà chúng tôi lưu giữ về bạn, bao gồm mọi dữ liệu bạn đã cung cấp cho chúng tôi. Bạn cũng có thể yêu cầu chúng tôi xóa mọi dữ liệu cá nhân mà chúng tôi lưu giữ về bạn. Điều này không bao gồm bất kỳ dữ liệu nào chúng tôi có nghĩa vụ giữ cho các mục đích hành chính, pháp lý hoặc bảo mật.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Dữ liệu của bạn được gửi đến đâu</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Văn bản được đề xuất: </strong>Các bình luận của khách (không phải là thành viên) có thể được kiểm tra thông qua dịch vụ tự động phát hiện bình luận rác.</p>\n<!-- /wp:paragraph -->\n','Chính sách bảo mật','','draft','closed','open','','chinh-sach-bao-mat','','','2026-09-10 15:11:04','2026-09-10 15:11:04','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/?page_id=3',0,'page','',0),(4,0,'2026-09-10 15:11:06','2026-09-10 15:11:06','<!-- wp:page-list /-->','Điều hướng','','publish','closed','closed','','navigation','','','2026-09-10 15:11:06','2026-09-10 15:11:06','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/index.php/2026/09/10/navigation/',0,'wp_navigation','',0),(5,0,'2026-09-10 22:13:53','2026-09-10 15:13:53','','Featured-Image-Post-1','','inherit','open','closed','','featured-image-post-1','','','2026-09-10 22:13:53','2026-09-10 15:13:53','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-1-featured.png',0,'attachment','image/png',0),(6,0,'2026-09-10 22:13:53','2026-09-10 15:13:53','','Illustration-1-Post-1','','inherit','open','closed','','illustration-1-post-1','','','2026-09-10 22:13:53','2026-09-10 15:13:53','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-1-detail-1.png',0,'attachment','image/png',0),(7,0,'2026-09-10 22:13:54','2026-09-10 15:13:54','','Illustration-2-Post-1','','inherit','open','closed','','illustration-2-post-1','','','2026-09-10 22:13:54','2026-09-10 15:13:54','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-1-detail-2.png',0,'attachment','image/png',0),(8,1,'2026-09-10 22:13:54','2026-09-10 15:13:54','<!-- wp:paragraph -->\n<p>Trí tuệ nhân tạo (AI) đang định hình lại toàn bộ nền kinh tế số toàn cầu. Từ các công cụ hỗ trợ viết mã nguồn, phân tích dữ liệu đến tự động hóa quy trình quản trị, AI giúp con người tối ưu hóa thời gian và nguồn lực.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":6,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-1-detail-1.png\" alt=\"Hình minh họa 1 - Trí Tuệ Nhân Tạo AI Đang Thay Đổi Cách Chúng Ta Làm Việc Như Thế Nào?\" class=\"wp-image-6\" /><figcaption>Hình 1: Minh họa tổng quan cho chủ đề Artificial Intelligence &amp; Future Work</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2>Điểm Nhấn Và Định Hướng Phát Triển</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Trong môi trường doanh nghiệp hiện đại, việc tích hợp AI không chỉ giúp nâng cao hiệu suất làm việc mà còn mở ra những phương thức sáng tạo hoàn toàn mới, đòi hỏi nhân sự phải không ngừng cập nhật kỹ năng công nghệ.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":7,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-1-detail-2.png\" alt=\"Hình minh họa 2 - Trí Tuệ Nhân Tạo AI Đang Thay Đổi Cách Chúng Ta Làm Việc Như Thế Nào?\" class=\"wp-image-7\" /><figcaption>Hình 2: Phân tích chuyên sâu và giải pháp thực tế</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><em>Bài viết thuộc chương trình thực hành CMS Lab 1 do sinh viên <strong>Bùi Nguyên Minh Quân</strong> thực hiện. Mọi thông tin phản ánh và thảo luận xin gửi về ban quản trị trang web.</em></p>\n<!-- /wp:paragraph -->','Trí Tuệ Nhân Tạo AI Đang Thay Đổi Cách Chúng Ta Làm Việc Như Thế Nào?','Khám phá sức ảnh hưởng sâu rộng của AI đối với năng suất làm việc và sự chuyển dịch của các ngành nghề.','publish','open','open','','tri-tue-nhan-tao-ai-dang-thay-doi-cach-chung-ta-lam-viec-nhu-the-nao','','','2026-09-10 22:13:54','2026-09-10 15:13:54','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/index.php/2026/09/10/tri-tue-nhan-tao-ai-dang-thay-doi-cach-chung-ta-lam-viec-nhu-the-nao/',0,'post','',0),(9,0,'2026-09-10 22:13:54','2026-09-10 15:13:54','','Featured-Image-Post-2','','inherit','open','closed','','featured-image-post-2','','','2026-09-10 22:13:54','2026-09-10 15:13:54','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-2-featured.png',0,'attachment','image/png',0),(10,0,'2026-09-10 22:13:54','2026-09-10 15:13:54','','Illustration-1-Post-2','','inherit','open','closed','','illustration-1-post-2','','','2026-09-10 22:13:54','2026-09-10 15:13:54','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-2-detail-1.png',0,'attachment','image/png',0),(11,0,'2026-09-10 22:13:54','2026-09-10 15:13:54','','Illustration-2-Post-2','','inherit','open','closed','','illustration-2-post-2','','','2026-09-10 22:13:54','2026-09-10 15:13:54','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-2-detail-2.png',0,'attachment','image/png',0),(12,1,'2026-09-10 22:13:55','2026-09-10 15:13:55','<!-- wp:paragraph -->\n<p>Hệ sinh thái nhà thông minh (Smarthome) đang ngày càng trở nên phổ biến với người dùng đô thị. Nhờ sự phát triển của kết nối vạn vật (IoT), các thiết bị như đèn chiếu sáng, máy điều hòa, khóa cửa thông minh đều có thể điều khiển qua điện thoại.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":10,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-2-detail-1.png\" alt=\"Hình minh họa 1 - Xu Hướng Thiết Bị Smarthome Tiện Nghi Trong Ngôi Nhà Hiện Đại\" class=\"wp-image-10\" /><figcaption>Hình 1: Minh họa tổng quan cho chủ đề Smart Home Ecosystem &amp; IoT</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2>Điểm Nhấn Và Định Hướng Phát Triển</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Việc ứng dụng các giải pháp tự động hóa giúp ngôi nhà trở nên an toàn hơn nhờ camera an ninh AI và cảm biến cảnh báo, đồng thời tối ưu hóa lượng điện năng tiêu thụ hàng tháng.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":11,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-2-detail-2.png\" alt=\"Hình minh họa 2 - Xu Hướng Thiết Bị Smarthome Tiện Nghi Trong Ngôi Nhà Hiện Đại\" class=\"wp-image-11\" /><figcaption>Hình 2: Phân tích chuyên sâu và giải pháp thực tế</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><em>Bài viết thuộc chương trình thực hành CMS Lab 1 do sinh viên <strong>Bùi Nguyên Minh Quân</strong> thực hiện. Mọi thông tin phản ánh và thảo luận xin gửi về ban quản trị trang web.</em></p>\n<!-- /wp:paragraph -->','Xu Hướng Thiết Bị Smarthome Tiện Nghi Trong Ngôi Nhà Hiện Đại','Hệ sinh thái thiết bị smarthome mang lại không gian sống tiện nghi, an toàn tuyệt đối và tiết kiệm điện.','publish','open','open','','xu-huong-thiet-bi-smarthome-tien-nghi-trong-ngoi-nha-hien-dai','','','2026-09-10 22:13:55','2026-09-10 15:13:55','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/index.php/2026/09/10/xu-huong-thiet-bi-smarthome-tien-nghi-trong-ngoi-nha-hien-dai/',0,'post','',0),(13,0,'2026-09-10 22:13:55','2026-09-10 15:13:55','','Featured-Image-Post-3','','inherit','open','closed','','featured-image-post-3','','','2026-09-10 22:13:55','2026-09-10 15:13:55','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-3-featured.png',0,'attachment','image/png',0),(14,0,'2026-09-10 22:13:55','2026-09-10 15:13:55','','Illustration-1-Post-3','','inherit','open','closed','','illustration-1-post-3','','','2026-09-10 22:13:55','2026-09-10 15:13:55','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-3-detail-1.png',0,'attachment','image/png',0),(15,0,'2026-09-10 22:13:55','2026-09-10 15:13:55','','Illustration-2-Post-3','','inherit','open','closed','','illustration-2-post-3','','','2026-09-10 22:13:55','2026-09-10 15:13:55','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-3-detail-2.png',0,'attachment','image/png',0),(16,1,'2026-09-10 22:13:55','2026-09-10 15:13:55','<!-- wp:paragraph -->\n<p>Để bắt đầu hành trình lập trình web, nền tảng vững chắc về HTML5, CSS3 và JavaScript là điều kiện tiên quyết. Đây là bộ ba trụ cột cấu tạo nên giao diện và tương tác của mọi website trên Internet.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":14,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-3-detail-1.png\" alt=\"Hình minh họa 1 - Lộ Trình Tự Học Lập Trình Web Từ Cơ Bản Đến Nâng Cao Cho Người Mới\" class=\"wp-image-14\" /><figcaption>Hình 1: Minh họa tổng quan cho chủ đề Web Development Roadmap 2026</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2>Điểm Nhấn Và Định Hướng Phát Triển</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Sau khi làm chủ kiến thức nền tảng, lập trình viên có thể mở rộng kỹ năng sang các công nghệ backend phổ biến như PHP, Node.js kết hợp cùng hệ thống quản trị cơ sở dữ liệu MySQL để xây dựng các ứng dụng hoàn chỉnh.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":15,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-3-detail-2.png\" alt=\"Hình minh họa 2 - Lộ Trình Tự Học Lập Trình Web Từ Cơ Bản Đến Nâng Cao Cho Người Mới\" class=\"wp-image-15\" /><figcaption>Hình 2: Phân tích chuyên sâu và giải pháp thực tế</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><em>Bài viết thuộc chương trình thực hành CMS Lab 1 do sinh viên <strong>Bùi Nguyên Minh Quân</strong> thực hiện. Mọi thông tin phản ánh và thảo luận xin gửi về ban quản trị trang web.</em></p>\n<!-- /wp:paragraph -->','Lộ Trình Tự Học Lập Trình Web Từ Cơ Bản Đến Nâng Cao Cho Người Mới','Hướng dẫn chi tiết lộ trình học lập trình web từ nền tảng HTML, CSS đến các framework hiện đại nhất.','publish','open','open','','lo-trinh-tu-hoc-lap-trinh-web-tu-co-ban-den-nang-cao-cho-nguoi-moi','','','2026-09-10 22:13:55','2026-09-10 15:13:55','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/index.php/2026/09/10/lo-trinh-tu-hoc-lap-trinh-web-tu-co-ban-den-nang-cao-cho-nguoi-moi/',0,'post','',0),(17,0,'2026-09-10 22:13:55','2026-09-10 15:13:55','','Featured-Image-Post-4','','inherit','open','closed','','featured-image-post-4','','','2026-09-10 22:13:55','2026-09-10 15:13:55','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-4-featured.png',0,'attachment','image/png',0),(18,0,'2026-09-10 22:13:56','2026-09-10 15:13:56','','Illustration-1-Post-4','','inherit','open','closed','','illustration-1-post-4','','','2026-09-10 22:13:56','2026-09-10 15:13:56','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-4-detail-1.png',0,'attachment','image/png',0),(19,0,'2026-09-10 22:13:56','2026-09-10 15:13:56','','Illustration-2-Post-4','','inherit','open','closed','','illustration-2-post-4','','','2026-09-10 22:13:56','2026-09-10 15:13:56','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-4-detail-2.png',0,'attachment','image/png',0),(20,1,'2026-09-10 22:13:56','2026-09-10 15:13:56','<!-- wp:paragraph -->\n<p>WordPress hiện đang cung cấp nền tảng cho hơn 40% website trên toàn cầu. Ưu thế lớn nhất của WordPress đến từ mã nguồn mở, cộng đồng nhà phát triển khổng lồ và kho thư viện theme, plugin phong phú bậc nhất.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":18,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-4-detail-1.png\" alt=\"Hình minh họa 1 - Tại Sao WordPress Vẫn Là Hệ Quản Trị Nội Dung CMS Số Một Thế Giới?\" class=\"wp-image-18\" /><figcaption>Hình 1: Minh họa tổng quan cho chủ đề WordPress CMS Domination &amp; Features</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2>Điểm Nhấn Và Định Hướng Phát Triển</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Từ các blog cá nhân đơn giản cho đến các cổng thông tin điện tử của doanh nghiệp lớn, WordPress luôn đáp ứng tính linh hoạt, khả năng tùy biến cao và hỗ trợ chuẩn SEO xuất sắc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":19,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-4-detail-2.png\" alt=\"Hình minh họa 2 - Tại Sao WordPress Vẫn Là Hệ Quản Trị Nội Dung CMS Số Một Thế Giới?\" class=\"wp-image-19\" /><figcaption>Hình 2: Phân tích chuyên sâu và giải pháp thực tế</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><em>Bài viết thuộc chương trình thực hành CMS Lab 1 do sinh viên <strong>Bùi Nguyên Minh Quân</strong> thực hiện. Mọi thông tin phản ánh và thảo luận xin gửi về ban quản trị trang web.</em></p>\n<!-- /wp:paragraph -->','Tại Sao WordPress Vẫn Là Hệ Quản Trị Nội Dung CMS Số Một Thế Giới?','Phân tích những ưu điểm vượt trội giúp WordPress thống trị thị trường website và quản trị nội dung số.','publish','open','open','','tai-sao-wordpress-van-la-he-quan-tri-noi-dung-cms-so-mot-the-gioi','','','2026-09-10 22:13:56','2026-09-10 15:13:56','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/index.php/2026/09/10/tai-sao-wordpress-van-la-he-quan-tri-noi-dung-cms-so-mot-the-gioi/',0,'post','',0),(21,0,'2026-09-10 22:13:56','2026-09-10 15:13:56','','Featured-Image-Post-5','','inherit','open','closed','','featured-image-post-5','','','2026-09-10 22:13:56','2026-09-10 15:13:56','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-5-featured.png',0,'attachment','image/png',0),(22,0,'2026-09-10 22:13:56','2026-09-10 15:13:56','','Illustration-1-Post-5','','inherit','open','closed','','illustration-1-post-5','','','2026-09-10 22:13:56','2026-09-10 15:13:56','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-5-detail-1.png',0,'attachment','image/png',0),(23,0,'2026-09-10 22:13:57','2026-09-10 15:13:57','','Illustration-2-Post-5','','inherit','open','closed','','illustration-2-post-5','','','2026-09-10 22:13:57','2026-09-10 15:13:57','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-5-detail-2.png',0,'attachment','image/png',0),(24,1,'2026-09-10 22:13:57','2026-09-10 15:13:57','<!-- wp:paragraph -->\n<p>Trong thời đại bùng nổ của mạng internet, dữ liệu cá nhân là tài sản vô cùng quý giá. Người dùng thường xuyên phải đối mặt với các nguy cơ lừa đảo trực tuyến, rò rỉ mật khẩu và chiếm đoạt danh tính số.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":22,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-5-detail-1.png\" alt=\"Hình minh họa 1 - Bảo Vệ Dữ Liệu Cá Nhân Và An Toàn Thông Tin Trong Kỷ Nguyên Số\" class=\"wp-image-22\" /><figcaption>Hình 1: Minh họa tổng quan cho chủ đề Personal Data Protection &amp; Security</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2>Điểm Nhấn Và Định Hướng Phát Triển</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Để tự bảo vệ mình, mỗi cá nhân cần kích hoạt xác thực hai yếu tố (2FA), sử dụng mật khẩu mạnh riêng biệt cho từng dịch vụ và cẩn trọng khi chia sẻ thông tin nhạy cảm trên các nền tảng mạng xã hội.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":23,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-5-detail-2.png\" alt=\"Hình minh họa 2 - Bảo Vệ Dữ Liệu Cá Nhân Và An Toàn Thông Tin Trong Kỷ Nguyên Số\" class=\"wp-image-23\" /><figcaption>Hình 2: Phân tích chuyên sâu và giải pháp thực tế</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><em>Bài viết thuộc chương trình thực hành CMS Lab 1 do sinh viên <strong>Bùi Nguyên Minh Quân</strong> thực hiện. Mọi thông tin phản ánh và thảo luận xin gửi về ban quản trị trang web.</em></p>\n<!-- /wp:paragraph -->','Bảo Vệ Dữ Liệu Cá Nhân Và An Toàn Thông Tin Trong Kỷ Nguyên Số','Những nguyên tắc vàng giúp bạn bảo vệ tài khoản mạng xã hội và thông tin cá nhân trước nguy cơ đánh cắp.','publish','open','open','','bao-ve-du-lieu-ca-nhan-va-an-toan-thong-tin-trong-ky-nguyen-so','','','2026-09-10 22:13:57','2026-09-10 15:13:57','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/index.php/2026/09/10/bao-ve-du-lieu-ca-nhan-va-an-toan-thong-tin-trong-ky-nguyen-so/',0,'post','',0),(25,0,'2026-09-10 22:13:57','2026-09-10 15:13:57','','Featured-Image-Post-6','','inherit','open','closed','','featured-image-post-6','','','2026-09-10 22:13:57','2026-09-10 15:13:57','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-6-featured.png',0,'attachment','image/png',0),(26,0,'2026-09-10 22:13:57','2026-09-10 15:13:57','','Illustration-1-Post-6','','inherit','open','closed','','illustration-1-post-6','','','2026-09-10 22:13:57','2026-09-10 15:13:57','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-6-detail-1.png',0,'attachment','image/png',0),(27,0,'2026-09-10 22:13:57','2026-09-10 15:13:57','','Illustration-2-Post-6','','inherit','open','closed','','illustration-2-post-6','','','2026-09-10 22:13:57','2026-09-10 15:13:57','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-6-detail-2.png',0,'attachment','image/png',0),(28,1,'2026-09-10 22:13:58','2026-09-10 15:13:58','<!-- wp:paragraph -->\n<p>Phương thức thanh toán quét mã VietQR và ví điện tử đã thâm nhập sâu rộng vào đời sống sinh hoạt, từ các trung tâm thương mại lớn đến các hàng quán vỉa hè, tạo nên trải nghiệm chi tiêu nhanh chóng.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":26,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-6-detail-1.png\" alt=\"Hình minh họa 1 - Thanh Toán Không Tiền Mặt: Thói Quen Tiêu Dùng Mới Của Giới Trẻ\" class=\"wp-image-26\" /><figcaption>Hình 1: Minh họa tổng quan cho chủ đề Cashless Payment &amp; Fintech Trends</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2>Điểm Nhấn Và Định Hướng Phát Triển</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Sự tiện lợi, tốc độ xử lý tức thì và các chương trình ưu đãi tích điểm đang dần thay thế hoàn toàn thói quen mang theo tiền mặt trong ví của đại đa số người tiêu dùng trẻ.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":27,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-6-detail-2.png\" alt=\"Hình minh họa 2 - Thanh Toán Không Tiền Mặt: Thói Quen Tiêu Dùng Mới Của Giới Trẻ\" class=\"wp-image-27\" /><figcaption>Hình 2: Phân tích chuyên sâu và giải pháp thực tế</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><em>Bài viết thuộc chương trình thực hành CMS Lab 1 do sinh viên <strong>Bùi Nguyên Minh Quân</strong> thực hiện. Mọi thông tin phản ánh và thảo luận xin gửi về ban quản trị trang web.</em></p>\n<!-- /wp:paragraph -->','Thanh Toán Không Tiền Mặt: Thói Quen Tiêu Dùng Mới Của Giới Trẻ','Ví điện tử và mã QR đã trở thành phương thức thanh toán quen thuộc, tiện lợi trong nhịp sống đô thị.','publish','open','open','','thanh-toan-khong-tien-mat-thoi-quen-tieu-dung-moi-cua-gioi-tre','','','2026-09-10 22:13:58','2026-09-10 15:13:58','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/index.php/2026/09/10/thanh-toan-khong-tien-mat-thoi-quen-tieu-dung-moi-cua-gioi-tre/',0,'post','',0),(29,0,'2026-09-10 22:13:58','2026-09-10 15:13:58','','Featured-Image-Post-7','','inherit','open','closed','','featured-image-post-7','','','2026-09-10 22:13:58','2026-09-10 15:13:58','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-7-featured.png',0,'attachment','image/png',0),(30,0,'2026-09-10 22:13:58','2026-09-10 15:13:58','','Illustration-1-Post-7','','inherit','open','closed','','illustration-1-post-7','','','2026-09-10 22:13:58','2026-09-10 15:13:58','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-7-detail-1.png',0,'attachment','image/png',0),(31,0,'2026-09-10 22:13:58','2026-09-10 15:13:58','','Illustration-2-Post-7','','inherit','open','closed','','illustration-2-post-7','','','2026-09-10 22:13:58','2026-09-10 15:13:58','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-7-detail-2.png',0,'attachment','image/png',0),(32,1,'2026-09-10 22:13:58','2026-09-10 15:13:58','<!-- wp:paragraph -->\n<p>Kính viễn vọng không gian James Webb của NASA là một trong những thành tựu khoa học vĩ đại nhất của nhân loại, hoạt động ở dải sóng hồng ngoại với độ phân giải siêu cao chưa từng có trong lịch sử thiên văn.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":30,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-7-detail-1.png\" alt=\"Hình minh họa 1 - Khám Phá Kính Viễn Vọng Không Gian James Webb Và Bí Ẩn Vũ Trụ\" class=\"wp-image-30\" /><figcaption>Hình 1: Minh họa tổng quan cho chủ đề James Webb Space Telescope Discoveries</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2>Điểm Nhấn Và Định Hướng Phát Triển</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Những bức ảnh chụp các chòm sao, tinh vân và thiên hà hình thành từ thuở sơ khai của vũ trụ đã cung cấp bằng chứng quý giá giúp các nhà khoa học giải mã nguồn gốc của các vì sao và hệ mặt trời.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":31,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-7-detail-2.png\" alt=\"Hình minh họa 2 - Khám Phá Kính Viễn Vọng Không Gian James Webb Và Bí Ẩn Vũ Trụ\" class=\"wp-image-31\" /><figcaption>Hình 2: Phân tích chuyên sâu và giải pháp thực tế</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><em>Bài viết thuộc chương trình thực hành CMS Lab 1 do sinh viên <strong>Bùi Nguyên Minh Quân</strong> thực hiện. Mọi thông tin phản ánh và thảo luận xin gửi về ban quản trị trang web.</em></p>\n<!-- /wp:paragraph -->','Khám Phá Kính Viễn Vọng Không Gian James Webb Và Bí Ẩn Vũ Trụ','Những hình ảnh kỳ vĩ và phát hiện đột phá về các thiên hà cổ đại từ kính viễn vọng không gian James Webb.','publish','open','open','','kham-pha-kinh-vien-vong-khong-gian-james-webb-va-bi-an-vu-tru','','','2026-09-10 22:13:58','2026-09-10 15:13:58','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/index.php/2026/09/10/kham-pha-kinh-vien-vong-khong-gian-james-webb-va-bi-an-vu-tru/',0,'post','',0),(33,0,'2026-09-10 22:13:59','2026-09-10 15:13:59','','Featured-Image-Post-8','','inherit','open','closed','','featured-image-post-8','','','2026-09-10 22:13:59','2026-09-10 15:13:59','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-8-featured.png',0,'attachment','image/png',0),(34,0,'2026-09-10 22:13:59','2026-09-10 15:13:59','','Illustration-1-Post-8','','inherit','open','closed','','illustration-1-post-8','','','2026-09-10 22:13:59','2026-09-10 15:13:59','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-8-detail-1.png',0,'attachment','image/png',0),(35,0,'2026-09-10 22:13:59','2026-09-10 15:13:59','','Illustration-2-Post-8','','inherit','open','closed','','illustration-2-post-8','','','2026-09-10 22:13:59','2026-09-10 15:13:59','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-8-detail-2.png',0,'attachment','image/png',0),(36,1,'2026-09-10 22:13:59','2026-09-10 15:13:59','<!-- wp:paragraph -->\n<p>Trước thách thức biến đổi khí hậu toàn cầu, việc chuyển dịch cơ cấu từ năng lượng hóa thạch sang năng lượng tái tạo như điện gió, điện mặt trời và thủy điện tích năng đang diễn ra mạnh mẽ.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":34,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-8-detail-1.png\" alt=\"Hình minh họa 1 - Năng Lượng Tái Tạo: Trụ Cột Cho Chiến Lược Phát Triển Xanh Bền Vững\" class=\"wp-image-34\" /><figcaption>Hình 1: Minh họa tổng quan cho chủ đề Renewable Energy &amp; Sustainable Growth</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2>Điểm Nhấn Và Định Hướng Phát Triển</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Các công nghệ lưu trữ năng lượng pin thể rắn và lưới điện thông minh hứa hẹn sẽ mang lại nguồn năng lượng sạch dồi dào, giảm thiểu tác động tiêu cực đến môi trường tự nhiên cho thế hệ mai sau.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":35,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-8-detail-2.png\" alt=\"Hình minh họa 2 - Năng Lượng Tái Tạo: Trụ Cột Cho Chiến Lược Phát Triển Xanh Bền Vững\" class=\"wp-image-35\" /><figcaption>Hình 2: Phân tích chuyên sâu và giải pháp thực tế</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><em>Bài viết thuộc chương trình thực hành CMS Lab 1 do sinh viên <strong>Bùi Nguyên Minh Quân</strong> thực hiện. Mọi thông tin phản ánh và thảo luận xin gửi về ban quản trị trang web.</em></p>\n<!-- /wp:paragraph -->','Năng Lượng Tái Tạo: Trụ Cột Cho Chiến Lược Phát Triển Xanh Bền Vững','Năng lượng mặt trời và gió đang giữ vai trò tiên phong trong công cuộc giảm phát thải khí nhà kính.','publish','open','open','','nang-luong-tai-tao-tru-cot-cho-chien-luoc-phat-trien-xanh-ben-vung','','','2026-09-10 22:13:59','2026-09-10 15:13:59','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/index.php/2026/09/10/nang-luong-tai-tao-tru-cot-cho-chien-luoc-phat-trien-xanh-ben-vung/',0,'post','',0),(37,0,'2026-09-10 22:13:59','2026-09-10 15:13:59','','Featured-Image-Post-9','','inherit','open','closed','','featured-image-post-9','','','2026-09-10 22:13:59','2026-09-10 15:13:59','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-9-featured.png',0,'attachment','image/png',0),(38,0,'2026-09-10 22:14:00','2026-09-10 15:14:00','','Illustration-1-Post-9','','inherit','open','closed','','illustration-1-post-9','','','2026-09-10 22:14:00','2026-09-10 15:14:00','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-9-detail-1.png',0,'attachment','image/png',0),(39,0,'2026-09-10 22:14:00','2026-09-10 15:14:00','','Illustration-2-Post-9','','inherit','open','closed','','illustration-2-post-9','','','2026-09-10 22:14:00','2026-09-10 15:14:00','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-9-detail-2.png',0,'attachment','image/png',0),(40,1,'2026-09-10 22:14:00','2026-09-10 15:14:00','<!-- wp:paragraph -->\n<p>Sử dụng phím tắt là cách nhanh nhất để tối ưu hóa thời gian thao tác trên máy tính. Các tổ hợp như Windows + V để mở lịch sử Clipboard, hay Windows + Shift + S để chụp màn hình là những công cụ vô cùng lợi hại.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":38,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-9-detail-1.png\" alt=\"Hình minh họa 1 - 10 Phím Tắt Tiện Dụng Trên Windows 11 Giúp Tăng Năng Suất Làm Việc\" class=\"wp-image-38\" /><figcaption>Hình 1: Minh họa tổng quan cho chủ đề Essential Windows 11 Shortcuts</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2>Điểm Nhấn Và Định Hướng Phát Triển</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Bên cạnh đó, tổ hợp Windows + Snap Layouts giúp phân chia cửa sổ làm việc thông minh trên các màn hình kích thước lớn, mang lại không gian làm việc khoa học và nâng cao khả năng tập trung.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":39,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-9-detail-2.png\" alt=\"Hình minh họa 2 - 10 Phím Tắt Tiện Dụng Trên Windows 11 Giúp Tăng Năng Suất Làm Việc\" class=\"wp-image-39\" /><figcaption>Hình 2: Phân tích chuyên sâu và giải pháp thực tế</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><em>Bài viết thuộc chương trình thực hành CMS Lab 1 do sinh viên <strong>Bùi Nguyên Minh Quân</strong> thực hiện. Mọi thông tin phản ánh và thảo luận xin gửi về ban quản trị trang web.</em></p>\n<!-- /wp:paragraph -->','10 Phím Tắt Tiện Dụng Trên Windows 11 Giúp Tăng Năng Suất Làm Việc','Bỏ túi các tổ hợp phím tắt trên Windows 11 giúp bạn thao tác đa nhiệm nhanh chóng và chuyên nghiệp hơn.','publish','open','open','','10-phim-tat-tien-dung-tren-windows-11-giup-tang-nang-suat-lam-viec','','','2026-09-10 22:14:00','2026-09-10 15:14:00','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/index.php/2026/09/10/10-phim-tat-tien-dung-tren-windows-11-giup-tang-nang-suat-lam-viec/',0,'post','',0),(41,0,'2026-09-10 22:14:00','2026-09-10 15:14:00','','Featured-Image-Post-10','','inherit','open','closed','','featured-image-post-10','','','2026-09-10 22:14:00','2026-09-10 15:14:00','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-10-featured.png',0,'attachment','image/png',0),(42,0,'2026-09-10 22:14:01','2026-09-10 15:14:01','','Illustration-1-Post-10','','inherit','open','closed','','illustration-1-post-10','','','2026-09-10 22:14:01','2026-09-10 15:14:01','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-10-detail-1.png',0,'attachment','image/png',0),(43,0,'2026-09-10 22:14:01','2026-09-10 15:14:01','','Illustration-2-Post-10','','inherit','open','closed','','illustration-2-post-10','','','2026-09-10 22:14:01','2026-09-10 15:14:01','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-10-detail-2.png',0,'attachment','image/png',0),(44,1,'2026-09-10 22:14:02','2026-09-10 15:14:02','<!-- wp:paragraph -->\n<p>Sau một thời gian sử dụng, máy tính Windows thường tích tụ nhiều file tạm, bộ nhớ đệm và các phần mềm chạy ngầm khi khởi động khiến tốc độ xử lý bị suy giảm rõ rệt.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":42,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-10-detail-1.png\" alt=\"Hình minh họa 1 - Cách Tối Ưu Hóa Tốc Độ Máy Tính Windows Chạy Nhanh Như Lúc Mới Mua\" class=\"wp-image-42\" /><figcaption>Hình 1: Minh họa tổng quan cho chủ đề PC Optimization &amp; Speed Boost Guide</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2>Điểm Nhấn Và Định Hướng Phát Triển</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Bằng cách vô hiệu hóa các ứng dụng khởi động không cần thiết trong Task Manager, dọn dẹp thư mục Temp và sử dụng công cụ Disk Cleanup, bạn hoàn toàn có thể khôi phục hiệu suất mượt mà cho chiếc máy tính của mình.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":43,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/BuiNguyenMinhQuan_CMS.git/wp-content/uploads/2026/09/post-10-detail-2.png\" alt=\"Hình minh họa 2 - Cách Tối Ưu Hóa Tốc Độ Máy Tính Windows Chạy Nhanh Như Lúc Mới Mua\" class=\"wp-image-43\" /><figcaption>Hình 2: Phân tích chuyên sâu và giải pháp thực tế</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><em>Bài viết thuộc chương trình thực hành CMS Lab 1 do sinh viên <strong>Bùi Nguyên Minh Quân</strong> thực hiện. Mọi thông tin phản ánh và thảo luận xin gửi về ban quản trị trang web.</em></p>\n<!-- /wp:paragraph -->','Cách Tối Ưu Hóa Tốc Độ Máy Tính Windows Chạy Nhanh Như Lúc Mới Mua','Tổng hợp các bước dọn rác hệ thống, quản lý ứng dụng khởi động để giải phóng bộ nhớ và tăng tốc PC.','publish','open','open','','cach-toi-uu-hoa-toc-do-may-tinh-windows-chay-nhanh-nhu-luc-moi-mua','','','2026-09-10 22:14:02','2026-09-10 15:14:02','',0,'http://localhost/BuiNguyenMinhQuan_CMS.git/index.php/2026/09/10/cach-toi-uu-hoa-toc-do-may-tinh-windows-chay-nhanh-nhu-luc-moi-mua/',0,'post','',0);
